import {sanitize,escapeXML,textToHTML} from './book-tools.mjs';
import {blobAsDataURL} from './importers.mjs';
import {optimizeRaster} from './media.mjs';
export function installEditorTools({save,toast}){
 const $=id=>document.getElementById(id),toolbar=document.querySelector('.toolbar');let editor=$('editor');const bound=new WeakSet(),histories=new WeakMap();let range=null,selectedImage=null,imageData='',replacing=false;let history=[editor.innerHTML],historyIndex=0,restoring=false;
 function record(){if(restoring||history[historyIndex]===editor.innerHTML)return;history=history.slice(0,historyIndex+1);history.push(editor.innerHTML);historyIndex++;while(history.length>30||history.length>2&&history.reduce((n,s)=>n+s.length,0)>20000000){history.shift();historyIndex--;}}
 function undo(delta){const next=historyIndex+delta;if(next<0||next>=history.length)return;historyIndex=next;restoring=true;editor.innerHTML=history[historyIndex];range=null;resetImage();save();restoring=false;}

 const extra=document.createElement('div');extra.className='advanced-tools';extra.innerHTML=`
 <div class="toolgroup"><button data-more="strikeThrough" title="Tachado">Tachado</button><button data-more="superscript" title="Sobrescrito">x²</button><button data-more="subscript" title="Subscrito">x₂</button><button data-more="insertOrderedList" title="Lista numerada">1. Lista</button><button data-more="indent" title="Aumentar recuo">Recuar →</button><button data-more="outdent" title="Diminuir recuo">← Recuo</button><button data-align="justify" title="Justificar texto">Justificar</button><button data-align="right" title="Alinhar à direita">À direita</button></div>
 <div class="toolgroup"><label>Tamanho <select id="textsize" aria-label="Tamanho do texto"><option value="">Selecionar</option><option value="0.85em">Pequeno</option><option value="1em">Normal</option><option value="1.25em">Grande</option><option value="1.5em">Muito grande</option></select></label><label>Cor <input id="textcolor" type="color" value="#25382f" aria-label="Cor do texto"></label><label>Realce <input id="textmark" type="color" value="#fff1a8" aria-label="Cor do realce"></label><button id="applymark">Realçar</button></div>
 <div class="toolgroup"><button id="insertfigure">＋ Figura</button><button id="inserttable">＋ Tabela</button><button id="insertbox">＋ Quadro</button><button id="insertrule">Linha divisória</button><button id="findreplace">Localizar / substituir</button></div>
 <div class="toolgroup selection-tools"><span id="selectionstatus">Selecione texto ou clique em uma figura.</span><button id="deleteselection">Excluir seleção</button><button id="replaceselection">Substituir seleção</button><button id="editfigure">Editar / substituir figura</button></div>
 <div id="tabletools" class="toolgroup" hidden><strong>Tabela</strong><button id="addtablerow">＋ Linha</button><button id="addtablecol">＋ Coluna</button><button id="deletetablerow">Excluir linha</button><button id="deletetablecol">Excluir coluna</button><button id="deletetable">Excluir tabela</button></div>`;toolbar.after(extra);
 const dialogs=document.createElement('div');dialogs.innerHTML=`
 <dialog id="figuredialog"><div class="dialogheading"><h2 id="figuretitle">Inserir figura</h2><button data-tool-close>Fechar</button></div><p>PNG, JPEG ou WebP. A imagem será otimizada e centralizada no EPUB.</p><label class="filelabel">Escolher arquivo<input id="figurefile" type="file" accept="image/png,image/jpeg,image/webp"></label><img id="figuredraft" alt="Prévia da figura" hidden><label>Descrição da imagem<input id="figurealt" placeholder="Descrição para acessibilidade"></label><label>Legenda (opcional)<input id="figurecaption" placeholder="Figura 1 — ..."></label><label>Largura <select id="figurewidth"><option value="100%">Largura disponível</option><option value="75%">75%</option><option value="50%">50%</option><option value="25%">25%</option></select></label><p id="figurestatus" role="status"></p><div class="actions"><button data-tool-close>Cancelar</button><button id="applyfigure" class="primary">Inserir figura</button></div></dialog>
 <dialog id="tabledialog"><div class="dialogheading"><h2>Inserir tabela</h2><button data-tool-close>Fechar</button></div><div class="formrow"><label>Linhas de dados<input id="tablerows" type="number" min="1" max="30" value="3"></label><label>Colunas<input id="tablecols" type="number" min="1" max="12" value="2"></label></div><label>Título (opcional)<input id="tablecaption"></label><label class="checkline"><input type="checkbox" id="tableheader" checked> Incluir cabeçalho de colunas</label><p>Edite as células diretamente no texto. Clique em uma célula para adicionar ou excluir linhas e colunas.</p><div class="actions"><button data-tool-close>Cancelar</button><button id="applytable" class="primary">Inserir tabela</button></div></dialog>
 <dialog id="boxdialog"><div class="dialogheading"><h2>Inserir quadro</h2><button data-tool-close>Fechar</button></div><label>Título<input id="boxtitle" placeholder="Quadro 1 — ..."></label><label>Conteúdo<textarea id="boxtext" placeholder="Texto do quadro"></textarea></label><div class="actions"><button data-tool-close>Cancelar</button><button id="applybox" class="primary">Inserir quadro</button></div></dialog>
 <dialog id="replacementdialog"><div class="dialogheading"><h2>Substituir seleção</h2><button data-tool-close>Fechar</button></div><p>Apenas o trecho selecionado será substituído. Para trocar uma imagem, use Editar / substituir figura.</p><textarea id="replacementtext" aria-label="Novo texto para seleção"></textarea><div class="actions"><button data-tool-close>Cancelar</button><button id="applyreplacement" class="primary">Substituir trecho</button></div></dialog>
 <dialog id="finddialog"><div class="dialogheading"><h2>Localizar e substituir</h2><button data-tool-close>Fechar</button></div><label>Localizar<input id="findtext"></label><label>Substituir por<input id="replacewith"></label><label class="checkline"><input type="checkbox" id="matchcase"> Diferenciar maiúsculas e minúsculas</label><p>Busca na área em edição (página atual ou texto corrido). A substituição mantém as imagens e a estrutura dos parágrafos.</p><p id="findstatus" role="status"></p><div class="actions"><button id="findnext">Localizar próximo</button><button id="replacefound">Substituir ocorrência</button><button id="replaceall" class="primary">Substituir todas</button></div></dialog>`;document.body.append(dialogs);
 dialogs.querySelectorAll('[data-tool-close]').forEach(b=>b.onclick=()=>b.closest('dialog').close());
 const inside=node=>node&&(node===editor||editor.contains(node.nodeType===1?node:node.parentNode));
 const remember=()=>{const selection=window.getSelection();if(selection?.rangeCount&&inside(selection.anchorNode)&&inside(selection.focusNode))range=selection.getRangeAt(0).cloneRange();};
 document.addEventListener('selectionchange',()=>{remember();if(selectedImage&&!editor.contains(selectedImage))selectedImage=null;const s=window.getSelection();$('selectionstatus').textContent=selectedImage?'Figura selecionada':s&&!s.isCollapsed&&inside(s.anchorNode)?s.toString().length+' caracteres selecionados':'Selecione texto ou clique em uma figura.';const node=range?.startContainer;const cell=(node?.nodeType===1?node:node?.parentElement)?.closest('td,th');$('tabletools').hidden=!cell||!editor.contains(cell);});
 extra.querySelectorAll('button').forEach(b=>b.onmousedown=e=>e.preventDefault());
 function restore(){editor.focus();const selection=window.getSelection();if(range&&inside(range.startContainer)&&inside(range.endContainer)){selection.removeAllRanges();selection.addRange(range);}else{const r=document.createRange();r.selectNodeContents(editor);r.collapse(false);selection.removeAllRanges();selection.addRange(r);range=r;}return selection;}
 function resetImage(){editor.querySelectorAll('.selected-media').forEach(i=>i.classList.remove('selected-media'));selectedImage=null;}
 function onEditorClick(e){resetImage();if(e.target.localName==='img'){selectedImage=e.target;selectedImage.classList.add('selected-media');const r=document.createRange();r.selectNode(selectedImage);range=r;const selection=window.getSelection();selection.removeAllRanges();selection.addRange(r);$('selectionstatus').textContent='Figura selecionada';}else remember();}
 function command(name,value){restore();document.execCommand(name,false,value);remember();save();}
 function insert(html){restore();document.execCommand('insertHTML',false,sanitize(html));resetImage();remember();save();}
 function blocks(){restore();const selected=range;return [...editor.querySelectorAll('p,h1,h2,h3,h4,h5,h6,blockquote,li,td,th')].filter(e=>selected?.intersectsNode(e)&&!e.querySelector('p,h1,h2,h3,li'));}
 function align(value){for(const e of blocks()){e.style.textAlign=value;e.setAttribute('data-editor-format','true');}save();}
 extra.querySelectorAll('[data-more]').forEach(b=>b.onclick=()=>command(b.dataset.more));extra.querySelectorAll('[data-align]').forEach(b=>b.onclick=()=>align(b.dataset.align));
 // Existing alignment buttons now mark explicit user choices for the EPUB.
 document.querySelector('[data-cmd="justifyLeft"]').onclick=()=>align('left');document.querySelector('[data-cmd="justifyCenter"]').onclick=()=>align('center');
 function inlineStyle(property,value){restore();const selection=window.getSelection();if(!selection||selection.isCollapsed){toast('Selecione o texto que deseja formatar.');return;}const selected=selection.getRangeAt(0),walker=document.createTreeWalker(editor,4),segments=[];let node;while((node=walker.nextNode()))if(selected.intersectsNode(node)&&node.textContent.length){const start=node===selected.startContainer?selected.startOffset:0,end=node===selected.endContainer?selected.endOffset:node.textContent.length;if(end>start)segments.push({node,start,end});}const spans=[];for(const item of segments.reverse()){const r=document.createRange();r.setStart(item.node,item.start);r.setEnd(item.node,item.end);const span=document.createElement('span');span.setAttribute('data-editor-format','true');span.style[property]=value;span.append(r.extractContents());r.insertNode(span);spans.unshift(span);}if(spans.length){const r=document.createRange();r.setStartBefore(spans[0]);r.setEndAfter(spans.at(-1));selection.removeAllRanges();selection.addRange(r);remember();save();}}
 $('textsize').onchange=()=>{if($('textsize').value)inlineStyle('fontSize',$('textsize').value);};$('textcolor').onchange=()=>inlineStyle('color',$('textcolor').value);$('applymark').onclick=()=>inlineStyle('backgroundColor',$('textmark').value);$('insertrule').onclick=()=>insert('<hr><p><br></p>');
 function openFigure(replace=false){remember();replacing=replace;imageData=replace&&selectedImage?selectedImage.src:'';$('figurealt').value=replace?selectedImage?.alt||'':'';$('figurecaption').value=replace?selectedImage?.closest('figure')?.querySelector('figcaption')?.textContent||'':'';$('figurewidth').value=replace?selectedImage?.getAttribute('data-media-width')||'100%':'100%';$('figurefile').value='';$('figuredraft').hidden=!imageData;$('figuredraft').src=imageData;$('figuretitle').textContent=replace?'Editar / substituir figura':'Inserir figura';$('applyfigure').textContent=replace?'Aplicar à figura':'Inserir figura';$('figurestatus').textContent='';$('figuredialog').showModal();}
 $('insertfigure').onclick=()=>openFigure();$('editfigure').onclick=()=>{if(!selectedImage){toast('Clique primeiro em uma figura do editor.');return;}openFigure(true);};
 $('figurefile').onchange=async e=>{const file=e.target.files[0];if(!file)return;if(file.size>30*1024*1024){toast('Use uma imagem de até 30 MB.');return;}$('applyfigure').disabled=true;$('figurestatus').textContent='Otimizando imagem…';try{const original=await blobAsDataURL(file),result=await optimizeRaster(original);imageData=result.data;$('figuredraft').src=imageData;$('figuredraft').hidden=false;$('figurestatus').textContent=result.width+' × '+result.height+' px · '+Math.ceil(result.bytes/1024)+' KB';}catch(err){$('figurestatus').textContent='Não foi possível abrir a imagem: '+err.message;}finally{$('applyfigure').disabled=false;}};
 $('applyfigure').onclick=()=>{if(!imageData){toast('Escolha uma imagem.');return;}$('figuredialog').close();const img=document.createElement('img');img.src=imageData;img.alt=$('figurealt').value;img.setAttribute('data-media-width',$('figurewidth').value);const figure=document.createElement('figure');figure.append(img);if($('figurecaption').value.trim()){const caption=document.createElement('figcaption');caption.textContent=$('figurecaption').value.trim();figure.append(caption);}if(replacing&&selectedImage&&editor.contains(selectedImage)){(selectedImage.closest('figure')||selectedImage).replaceWith(figure);resetImage();save();}else insert(figure.outerHTML+'<p><br></p>');$('figuredialog').close();};
 $('inserttable').onclick=()=>{remember();$('tabledialog').showModal();};$('applytable').onclick=()=>{const rows=Number($('tablerows').value),cols=Number($('tablecols').value);if(!Number.isInteger(rows)||!Number.isInteger(cols)||rows<1||rows>30||cols<1||cols>12){toast('Use de 1 a 30 linhas e de 1 a 12 colunas.');return;}let html='<table>';if($('tablecaption').value)html+='<caption>'+escapeXML($('tablecaption').value)+'</caption>';if($('tableheader').checked)html+='<thead><tr>'+Array.from({length:cols},(_,i)=>'<th>Coluna '+(i+1)+'</th>').join('')+'</tr></thead>';html+='<tbody>'+Array.from({length:rows},()=>'<tr>'+Array.from({length:cols},()=>'<td><p><br></p></td>').join('')+'</tr>').join('')+'</tbody></table><p><br></p>';$('tabledialog').close();insert(html);};
 $('insertbox').onclick=()=>{remember();$('boxdialog').showModal();};$('applybox').onclick=()=>{$('boxdialog').close();insert('<table>' + ($('boxtitle').value?'<caption>'+escapeXML($('boxtitle').value)+'</caption>':'')+'<tbody><tr><td>'+textToHTML($('boxtext').value||'Texto do quadro',{reconstruct:false,headings:false})+'</td></tr></tbody></table><p><br></p>');$('boxdialog').close();};
 function removeSelection(){restore();const sel=window.getSelection();if(sel.isCollapsed&&!selectedImage){toast('Selecione um trecho ou clique em uma figura para excluir.');return;}if(selectedImage){(selectedImage.closest('figure')||selectedImage).remove();resetImage();save();}else command('delete');}
 $('deleteselection').onclick=removeSelection;$('replaceselection').onclick=()=>{if(selectedImage){openFigure(true);return;}restore();const sel=window.getSelection();if(sel.isCollapsed){toast('Selecione o trecho que deseja substituir.');return;}$('replacementtext').value=sel.toString();remember();$('replacementdialog').showModal();};$('applyreplacement').onclick=()=>{$('replacementdialog').close();command('insertText',$('replacementtext').value);$('replacementdialog').close();};
 function activeCell(){restore();const n=range?.startContainer;const cell=(n?.nodeType===1?n:n?.parentElement)?.closest('td,th');return cell&&editor.contains(cell)?cell:null;}
 function tableAction(fn){const cell=activeCell();if(!cell){toast('Clique em uma célula da tabela.');return;}fn(cell,cell.closest('table'));range=null;save();$('tabletools').hidden=true;}
 $('addtablerow').onclick=()=>tableAction((cell)=>{const row=cell.parentElement,next=document.createElement('tr');for(const old of row.children){const td=document.createElement('td');if(old.colSpan>1)td.colSpan=old.colSpan;td.innerHTML='<p><br></p>';next.append(td);}if(row.parentElement.localName==='thead'){const body=row.closest('table').tBodies[0]||row.closest('table').createTBody();body.prepend(next);}else row.after(next);});
 $('addtablecol').onclick=()=>tableAction((cell,table)=>{if(table.querySelector('[colspan],[rowspan]')){toast('Para adicionar colunas, use uma tabela sem células mescladas.');return;}const index=cell.cellIndex;for(const row of table.rows){const td=document.createElement(row.parentElement.localName==='thead'?'th':'td');td.innerHTML='<br>';row.cells[index]?.after(td);}});
 $('deletetablerow').onclick=()=>tableAction((cell,table)=>{if(table.querySelector('[rowspan]')){toast('Não é possível excluir linhas com células mescladas verticalmente.');return;}cell.parentElement.remove();if(!table.rows.length)table.remove();});$('deletetablecol').onclick=()=>tableAction((cell,table)=>{if(table.querySelector('[colspan],[rowspan]')){toast('Para excluir colunas, use uma tabela sem células mescladas.');return;}const index=cell.cellIndex;for(const row of [...table.rows])row.cells[index]?.remove();if(!table.querySelector('td,th'))table.remove();});$('deletetable').onclick=()=>tableAction((_,table)=>table.remove());
 let found=null,lastEnd=0;
 function textMap(){const walker=document.createTreeWalker(editor,4),entries=[];let n,text='',previous=null;while((n=walker.nextNode())){const block=n.parentElement?.closest('p,li,h1,h2,h3,h4,h5,h6,td,th,div,figcaption,blockquote');if(previous&&block!==previous)text+='\n';previous=block;entries.push({node:n,start:text.length,end:text.length+n.textContent.length});text+=n.textContent;}return {text,entries};}
 function matchRange(map,start,end){const first=map.entries.find(e=>e.end>start),last=map.entries.find(e=>e.end>=end);if(!first||!last)return null;const r=document.createRange();r.setStart(first.node,start-first.start);r.setEnd(last.node,end-last.start);return r;}
 function findNext(){const needle=$('findtext').value;if(!needle)return;const map=textMap(),s=$('matchcase').checked?map.text:map.text.toLocaleLowerCase(),q=$('matchcase').checked?needle:needle.toLocaleLowerCase();let at=s.indexOf(q,lastEnd);if(at<0)at=s.indexOf(q);if(at<0){found=null;$('findstatus').textContent='Texto não encontrado.';return;}found=matchRange(map,at,at+needle.length);lastEnd=at+needle.length;range=found.cloneRange();const selection=window.getSelection();selection.removeAllRanges();selection.addRange(range);$('findstatus').textContent='Ocorrência selecionada na área em edição.';}
 $('findreplace').onclick=()=>{remember();found=null;lastEnd=0;$('findstatus').textContent='';$('finddialog').showModal();};$('findtext').oninput=()=>{found=null;lastEnd=0;};$('findnext').onclick=findNext;$('replacefound').onclick=()=>{if(!found){findNext();return;}range=found.cloneRange();$('finddialog').close();command('insertText',$('replacewith').value);$('finddialog').showModal();found=null;lastEnd=0;$('findstatus').textContent='Ocorrência substituída.';};
 $('replaceall').onclick=()=>{const needle=$('findtext').value;if(!needle)return;const map=textMap(),s=$('matchcase').checked?map.text:map.text.toLocaleLowerCase(),q=$('matchcase').checked?needle:needle.toLocaleLowerCase(),matches=[];let at=0;while((at=s.indexOf(q,at))>=0){matches.push([at,at+needle.length]);at+=needle.length;}for(const [start,end]of matches.reverse()){const r=matchRange(map,start,end);if(!r)continue;r.deleteContents();r.insertNode(document.createTextNode($('replacewith').value));}found=null;lastEnd=0;range=null;save();$('findstatus').textContent=matches.length+' ocorrência(s) substituída(s).';};
 document.querySelectorAll('[data-cmd]').forEach(b=>{if(!['justifyLeft','justifyCenter'].includes(b.dataset.cmd))b.onclick=()=>command(b.dataset.cmd);});
 document.querySelector('[data-cmd="undo"]').onclick=()=>undo(-1);document.querySelector('[data-cmd="redo"]').onclick=()=>undo(1);
 const format=$('format');if(format)format.onchange=()=>command('formatBlock',format.value);const clean=$('clean');if(clean)clean.onclick=()=>command('removeFormat');
 function attach(target){if(bound.has(target))return;bound.add(target);target.addEventListener('click',onEditorClick);target.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&['z','y'].includes(e.key.toLowerCase())){e.preventDefault();undo(e.key.toLowerCase()==='y'||e.shiftKey?1:-1);}});}
 attach(editor);
 return {record,insertHTML:insert,setTarget(target){if(!target||target===editor)return;histories.set(editor,{history,historyIndex});resetImage();editor=target;range=null;attach(editor);const prior=histories.get(target);history=prior?.history||[editor.innerHTML];historyIndex=prior?.historyIndex||0;$('tabletools').hidden=true;},reset(){range=null;resetImage();history=[editor.innerHTML];historyIndex=0;$('tabletools').hidden=true;}};
}
